{
  "implementation": "def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    n = len(segments)
    allocs = [seg["minimum"] for seg in segments]
    caps = [seg["capacity"] for seg in segments]
    remaining = budget - sum(allocs)
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if allocs[i] < caps[i]:
                score = seg["importance"] / (allocs[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break
        allocs[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]["name"]: allocs[i] for i in range(n)}
    return {"allocations": allocs, "by_name": by_name, "total": sum(allocs)}
